function toBool(v){
 if (v===true || v===false) return v;
 if (typeof v === 'number') return v !== 0;
 if (typeof v === 'string'){
  const s=v.trim().toLowerCase();
  if(['on','true','1','yes','enabled','production'].includes(s)) return true;
  if(['off','false','0','no','disabled','test'].includes(s)) return false;
 }
 if (v && typeof v === 'object'){
  if (v.enabled !== undefined) return toBool(v.enabled);
  if (v.state !== undefined) return toBool(v.state);
 }
 return null;
}
const enabled = toBool(msg.payload);
if (enabled === null) return null;
flow.set('sirensEnabled', enabled);
node.status({fill: enabled?'green':'yellow', shape:'dot', text: enabled?'sirens ON':'sirens OFF'});
if (!enabled) return [null, {payload:{stop:true}}];
return [msg, null];

const cfg = flow.get('z2mSafetyCfg') || {};
const payload = msg.payload || {};
const p = String(msg.topic || '').split('/');
const base = p[0] || '';
const dev = p[1] || '';

function inList(list){ return (list || []).some(i => i.baseTopic === base && i.name === dev); }

if ((inList(cfg.silenceButtons) || inList(cfg.sirens)) && payload.action) {
  msg.event = { type:'silence', baseTopic: base, device: dev, action: String(payload.action), ts: Date.now() };
  return msg;
}

if (cfg.smokeHushAsSilence && inList(cfg.smokeSensors)) {
  if (payload.buzzer_manual_mute === true || payload.hush === true || payload.test === true || payload.selftest === true) {
    msg.event = { type:'silence', baseTopic: base, device: dev, action:'hush', ts: Date.now() };
    return msg;
  }
}

if (inList(cfg.floodSensors)) {
  const active = payload.water_leak === true || payload.water_leak === 1 || payload.leak === true || payload.flood === true;
  msg.event = { type:'flood', active: !!active, baseTopic: base, device: dev, ts: Date.now() };
  return msg;
}

if (inList(cfg.smokeSensors)) {
  const active = payload.smoke === true || payload.smoke === 1 || payload.alarm === true || payload.alarm === 1 || payload.smoke_alarm === true || payload.fire === true;
  const area = (cfg.workshopBaseTopics || []).includes(base) ? 'workshop' : ((cfg.homeBaseTopics || []).includes(base) ? 'home' : 'unknown');
  msg.event = { type:'smoke', active: !!active, area, baseTopic: base, device: dev, ts: Date.now() };
  return msg;
}

if (inList(cfg.heatSensors)) {
  const raw = payload.temperature !== undefined ? payload.temperature : (payload.temp !== undefined ? payload.temp : payload.device_temperature);
  const t = Number(raw);
  const thr = Number(cfg.heatThresholdC || 45);
  msg.event = { type:'heat', active: Number.isFinite(t) && t >= thr, temperature:t, threshold:thr, baseTopic:base, device:dev, ts: Date.now() };
  return msg;
}

return null;

const cfg = flow.get('z2mSafetyCfg') || {};
const ev = msg.event;
const key = `${ev.baseTopic}/${ev.device}`;
const active = flow.get('floodActive') || {};
const wet = flow.get('floodLastWetTs') || {};
const dry = flow.get('floodLastDryTs') || {};

if (ev.active) {
  wet[key] = ev.ts;
  flow.set('floodLastWetTs', wet);
  if (active[key]) return null;
  active[key] = true;
  flow.set('floodActive', active);
  flow.set('pumpsForcedOff', true);

  msg.alarm = { kind:'flood', action:'start', source:key, ts:ev.ts };
  msg.title = `FLOOD detected: ${ev.device}`;
  msg.message = `Water leak detected on ${key}.`;
  msg.shutdownPumps = true;
  return msg;
}

dry[key] = ev.ts;
flow.set('floodLastDryTs', dry);
if (!active[key]) return null;
delete active[key];
flow.set('floodActive', active);

msg.alarm = { kind:'flood', action:'cleared', source:key, ts:ev.ts };
msg.title = `FLOOD cleared: ${ev.device}`;
msg.message = `Water leak cleared on ${key}.`;
msg.shutdownPumps = false;
msg.restoreDelayCheck = Object.keys(active).length === 0;
return msg;

const ev = msg.event;
const key = `${ev.baseTopic}/${ev.device}`;
const active = flow.get('smokeActive') || {};
if (ev.active) {
  if (active[key]) return null;
  active[key] = true;
  flow.set('smokeActive', active);
  const beeps = ev.area === 'workshop' ? 2 : 3;
  flow.set('smokeBeepCount', beeps);
  msg.alarm = { kind:'smoke', action:'start', source:key, area:ev.area, beeps, ts:ev.ts };
  msg.title = `SMOKE detected: ${ev.device}`;
  msg.message = `Smoke alarm from ${key} (${ev.area}).`;
  msg.shutdownPumps = false;
  return msg;
}
if (!active[key]) return null;
delete active[key];
flow.set('smokeActive', active);
msg.alarm = { kind:'smoke', action:'cleared', source:key, area:ev.area, ts:ev.ts };
msg.title = `SMOKE cleared: ${ev.device}`;
msg.message = `Smoke cleared on ${key}.`;
msg.shutdownPumps = false;
return msg;

const ev = msg.event;
const key = `${ev.baseTopic}/${ev.device}`;
const active = flow.get('heatActive') || {};
if (ev.active) {
  if (active[key]) return null;
  active[key] = true;
  flow.set('heatActive', active);
  msg.alarm = { kind:'heat', action:'start', source:key, temperature:ev.temperature, threshold:ev.threshold, ts:ev.ts };
  msg.title = `HEAT detected: ${ev.device}`;
  msg.message = `High temperature on ${key}: ${ev.temperature}C >= ${ev.threshold}C.`;
  msg.shutdownPumps = false;
  return msg;
}
if (!active[key]) return null;
delete active[key];
flow.set('heatActive', active);
msg.alarm = { kind:'heat', action:'cleared', source:key, temperature:ev.temperature, threshold:ev.threshold, ts:ev.ts };
msg.title = `HEAT cleared: ${ev.device}`;
msg.message = `Temperature normalized on ${key}.`;
msg.shutdownPumps = false;
return msg;

const cfg = flow.get('z2mSafetyCfg') || {};
const ev = msg.event;
const now = Date.now();
const src = `${ev.baseTopic}/${ev.device}`;
const state = flow.get('silencePress') || {};
const prev = state[src] || {count:0,last:0};
const win = Number(cfg.resetPressWindowSec || 5) * 1000;
const count = (now - prev.last) <= win ? prev.count + 1 : 1;
state[src] = {count,last:now};
flow.set('silencePress', state);
flow.set('silencedUntil', now + Number(cfg.silenceMinutes || 60) * 60 * 1000);

msg.alarm = { kind:'silence', action:'pressed', source:src, presses:count, ts:now };
msg.title = 'Alarms silenced';
msg.message = `Silenced by ${src}.`;
msg.stopSirens = true;
msg.resetLoops = false;

if (count >= Number(cfg.resetPressCount || 3)) {
  state[src] = {count:0,last:0};
  flow.set('silencePress', state);
  msg.alarm = { kind:'silence', action:'reset', source:src, presses:count, ts:now };
  msg.title = 'Alarms reset requested';
  msg.message = `Reset requested by ${src}.`;
  msg.resetLoops = true;
  msg.restorePumpsRequested = true;
  msg.immediateRestoreIfDry = true;
}
return msg;

const cfg = flow.get('z2mSafetyCfg') || {};
const now = Date.now();
const minMs = Number(cfg.floodDryMinutes || 5) * 60 * 1000;
const active = flow.get('floodActive') || {};
const dry = flow.get('floodLastDryTs') || {};
const list = cfg.floodSensors || [];

if (flow.get('pumpsForcedOff') !== true) return null;
const allInactive = list.every(s => !active[`${s.baseTopic}/${s.name}`]);
const allDry = list.every(s => {
  const k = `${s.baseTopic}/${s.name}`;
  return typeof dry[k] === 'number' && (now - dry[k]) >= minMs;
});
if (!(allInactive && allDry)) return null;

msg.restorePumpsRequested = true;
msg.immediateRestoreIfDry = false;
msg.alarm = { kind:'flood', action:'restored', source:'auto', ts: now };
msg.title = 'Flood reset complete';
msg.message = 'All flood sensors dry for 5 minutes. Pumps will be restored.';
return msg;

const fa = Object.keys(flow.get('floodActive') || {}).length;
const sa = Object.keys(flow.get('smokeActive') || {}).length;
const ha = Object.keys(flow.get('heatActive') || {}).length;
if (fa || sa || ha) return null;
msg.resetLoops = true;
msg.alarm = { kind:'system', action:'all_clear', ts: Date.now() };
msg.title = 'All alarms cleared';
msg.message = 'All monitored sensors returned to normal.';
return msg;

const cfg = flow.get('z2mSafetyCfg') || {};

function parseService(s) {
  const p = String(s || '').split('.');
  return { domain: p[0] || '', service: p.slice(1).join('.') || '' };
}
function haCall(domain, service, data) {
  return {
    method: 'POST',
    url: `${cfg.haBaseUrl || 'http://supervisor/core'}/api/services/${domain}/${service}`,
    headers: { Authorization: `Bearer ${cfg.haToken || ''}`, 'Content-Type': 'application/json' },
    payload: data,
  };
}

const haCalls = [];

if (msg.shutdownPumps === true) {
  flow.set('pumpsForcedOff', true);
  msg.pumpMqtt = (cfg.pumpOutletsZ2M || []).map(p => ({ topic: `${p.baseTopic}/${p.name}/set`, payload: { state: 'OFF' } }));
}

if (msg.restorePumpsRequested === true) {
  const now = Date.now();
  const minMs = Number(cfg.floodDryMinutes || 5) * 60 * 1000;
  const active = flow.get('floodActive') || {};
  const dry = flow.get('floodLastDryTs') || {};
  const list = cfg.floodSensors || [];
  const allInactive = list.every(s => !active[`${s.baseTopic}/${s.name}`]);
  const allDry = list.every(s => {
    const k = `${s.baseTopic}/${s.name}`;
    return typeof dry[k] === 'number' && (now - dry[k]) >= minMs;
  });

  if (flow.get('pumpsForcedOff') === true && allInactive && allDry) {
    msg.pumpMqtt = (cfg.pumpOutletsZ2M || []).map(p => ({ topic: `${p.baseTopic}/${p.name}/set`, payload: { state: 'ON' } }));
    flow.set('pumpsForcedOff', false);
    flow.set('silencedUntil', 0);
  }
}

if (msg.alarm && msg.alarm.kind) {
  msg._siren = { kind: msg.alarm.kind, action: msg.alarm.action, beeps: msg.alarm.beeps || 1 };
}

if (msg.title && msg.message) {
  const svc = parseService(cfg.notifyPushService || 'notify.notify');
  if (svc.domain && svc.service) haCalls.push(haCall(svc.domain, svc.service, { title: msg.title, message: msg.message }));
}

msg.haCalls = haCalls;
return [msg, msg];

const calls = msg.haCalls || [];
if (!calls.length) return null;
return [calls.map(c => ({ method:c.method, url:c.url, headers:c.headers, payload:c.payload }))];

const cfg = flow.get('z2mSafetyCfg') || {};
const to = (cfg.emailTo || []).filter(Boolean);
if (!to.length || !msg.title || !msg.message) return null;
msg.to = to.join(',');
msg.topic = msg.title;
msg.payload = msg.message;
return msg;

const cfg = flow.get('z2mSafetyCfg') || {};
if (msg.reset === true) return null;
const active = flow.get('floodActive') || {};
if (Object.keys(active).length === 0) return null;
const outNow = { payload: { pattern:'flood', beeps:1 } };
const outNext = { delay: Number(cfg.floodRepeatSeconds || 150) * 1000 };
return [[outNow],[outNext]];

const cfg = flow.get('z2mSafetyCfg') || {};
if (msg.reset === true) return null;
const active = flow.get('smokeActive') || {};
if (Object.keys(active).length === 0) return null;
const outNow = { payload: { pattern:'smoke', beeps:1 } };
const outNext = { delay: Number(cfg.smokeRepeatSeconds || 120) * 1000 };
return [[outNow],[outNext]];

const cfg = flow.get('z2mSafetyCfg') || {};
if (msg.reset === true) return null;
const active = flow.get('heatActive') || {};
if (Object.keys(active).length === 0) return null;
const outNow = { payload: { pattern:'heat', beeps:1 } };
const outNext = { delay: Number(cfg.heatRepeatSeconds || 180) * 1000 };
return [[outNow],[outNext]];

if (flow.get('sirensEnabled') !== true) return null;
const until = flow.get('silencedUntil') || 0;
if (Date.now() < until) return null;
return msg;

const cfg = flow.get('z2mSafetyCfg') || {};
const kind = (msg.payload && msg.payload.pattern) || 'flood';
const tpl = (cfg.sirenTemplates || {})[kind] || (cfg.sirenTemplates || {}).flood || { warning:{ mode:'emergency', duration:2 } };
let beeps = (msg.payload && msg.payload.beeps) || 1;
if (kind === 'smoke') {
  const s = flow.get('smokeBeepCount');
  if (Number.isFinite(s)) beeps = s;
}
const out = [];
let delay = 0;
for (let i=0; i<beeps; i++) {
  for (const s of (cfg.sirens || [])) {
    out.push({ topic: `${s.baseTopic}/${s.name}/set`, payload: tpl, delay });
  }
  delay += 700;
}
return [out];

const cfg = flow.get('z2mSafetyCfg') || {};
const stop = ((cfg.sirenTemplates || {}).stop) || { warning:{ mode:'stop' } };
const out = (cfg.sirens || []).map(s => ({ topic: `${s.baseTopic}/${s.name}/set`, payload: stop }));
return [out];

const list = msg.pumpMqtt || [];
if (!list.length) return null;
return [list];
